module multi_pipe_8bit #(
    parameter size = 8
) (
    input clk,
    input rst_n,
    input [size-1:0] mul_a,
    input [size-1:0] mul_b,
    input mul_en_in,
    output reg mul_en_out,
    output reg [size*2-1:0] mul_out
);

reg [1:0] mul_en_out_reg;
reg [7:0] mul_a_reg;
reg [7:0] mul_b_reg;
reg [15:0] temp [0:7];
reg [15:0] sum [0:3];
reg [15:0] mul_out_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin

        mul_en_out_reg <= 2'b0;
        mul_a_reg <= 8'b0;
        mul_b_reg <= 8'b0;
        temp[0] <= 16'b0;
        temp[1] <= 16'b0;
        temp[2] <= 16'b0;
        temp[3] <= 16'b0;
        temp[4] <= 16'b0;
        temp[5] <= 16'b0;
        temp[6] <= 16'b0;
        temp[7] <= 16'b0;
        sum[0] <= 16'b0;
        sum[1] <= 16'b0;
        sum[2] <= 16'b0;
        sum[3] <= 16'b0;
        mul_out_reg <= 16'b0;
    end else begin

        mul_en_out_reg <= {mul_en_out_reg[0], mul_en_in};

        if (mul_en_out_reg[0]) begin
            mul_a_reg <= mul_a;
            mul_b_reg <= mul_b;
        end

        temp[0] <= {{8{mul_b_reg[0]}}, mul_a_reg} << 0;
        temp[1] <= {{8{mul_b_reg[1]}}, mul_a_reg} << 1;
        temp[2] <= {{8{mul_b_reg[2]}}, mul_a_reg} << 2;
        temp[3] <= {{8{mul_b_reg[3]}}, mul_a_reg} << 3;
        temp[4] <= {{8{mul_b_reg[4]}}, mul_a_reg} << 4;
        temp[5] <= {{8{mul_b_reg[5]}}, mul_a_reg} << 5;
        temp[6] <= {{8{mul_b_reg[6]}}, mul_a_reg} << 6;
        temp[7] <= {{8{mul_b_reg[7]}}, mul_a_reg} << 7;

        sum[0] <= temp[0];
        sum[1] <= sum[0] + temp[1];
        sum[2] <= sum[1] + temp[2];
        sum[3] <= sum[2] + temp[3];

        mul_out_reg <= sum[0] + sum[1] + sum[2] + sum[3];
    end
end

assign mul_en_out = mul_en_out_reg[1];
assign mul_out = mul_en_out_reg[1] ? mul_out_reg : 16'b0;
endmodule
